#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
  set +x
  TOTAL_STAGES=7
  [[ -t 0 && -t 1 ]] || { printf 'Run this wizard in an interactive terminal.\n' >&2; return 1; }

  # Only non-secret setup metadata is saved. Never source the resulting file.
  local setup_dir provider_scope
  if [[ -n "${LOCALAPPDATA:-}" ]] && command -v cygpath >/dev/null 2>&1; then
    setup_dir="$(cygpath -u "$LOCALAPPDATA")/Slander/o-01"
  elif [[ -n "${WSL_DISTRO_NAME:-}" ]]; then
    printf 'Use Git Bash on Windows for this wizard, so metadata stays outside OneDrive.\n' >&2
    return 1
  else
    setup_dir="${XDG_CONFIG_HOME:-${HOME:?}/.config}/slander/o-01"
  fi
  ENV_FILE="$setup_dir/setup.env"

  # These helpers extend the stages, without changing the template library.
  capture() {
    local key="$1" prompt="$2" pattern="$3"
    while true; do
      ask "$key" "$prompt" || return 1
      if [[ -z "${!key}" ]]; then
        say 'Left pending; you can rerun this wizard later.'
        return 1
      fi
      if [[ "${!key}" =~ $pattern ]]; then
        write_env "$key" "${!key}"
        return 0
      fi
      say 'Use the requested value only; do not paste tokens, URLs, passwords or personal details.'
    done
  }
  checkpoint() {
    local key="$1" question="$2"
    if confirm "$question"; then
      write_env "$key" 'operator_confirmed'
    else
      write_env "$key" 'pending'
      SKIPPED+=("$key")
    fi
  }
  local text_pattern='^[a-zA-Z0-9_ .,:+()/=>-]+$'

  banner 'O-01: account setup and approval checkpoints'
  stage 'Review and approve the setup stages'
  say '1. Choose providers and approve this local metadata file.'
  say '2. Meta: sign in and select an isolated developer app.'
  say '3. Meta: select the ad account and approve its reporting access.'
  say '4. TikTok: sign in and select an isolated API for Business app.'
  say '5. TikTok: select the advertiser account and approve its reporting role.'
  say '6. TikTok: review advertiser consent, only if a working callback is ready.'
  say '7. Record representative-history availability and review the handoff.'
  say "Values are saved to: $ENV_FILE"
  say 'Saved values: provider choice, app/account IDs, zones, roles, permission labels and setup status.'
  say 'These are local setup records, not verified API grants or passed reporting tests.'
  say 'No API calls, CI secret changes, ad purchases, billing setup or token revocation are performed.'
  say 'Credentials, app secrets, auth codes and authorization URLs stay in provider tools.'
  if ! confirm 'Approve these stages and this metadata destination?'; then
    say 'Stopped without creating a metadata file. Adjust the plan before rerunning.'
    return 0
  fi
  read -r -p '  Providers [both/meta/tiktok; Enter = both]: ' provider_scope
  provider_scope="${provider_scope:-both}"
  case "$provider_scope" in both|meta|tiktok) ;; *) say 'Unknown provider choice; stopped.'; return 1 ;; esac
  [[ ! -L "$setup_dir" && ! -L "$ENV_FILE" ]] || { say 'Metadata destination is a symlink; stopped.'; return 1; }
  (umask 077 && mkdir -p "$setup_dir")
  write_env O01_PROVIDERS "$provider_scope"
  write_env O01_SETUP_STATUS 'in_progress'
  write_env O01_ACCOUNT_VALIDATION 'not_run'

  stage 'Meta: developer login and app selection'
  if [[ "$provider_scope" != tiktok ]]; then
    open_url 'https://developers.facebook.com/apps/'
    step 'Sign in yourself and select the isolated app intended for reporting validation.'
    step 'Use App settings > Basic to locate the App ID, if this screen is available.'
    say 'Meta setup documentation returned HTTP 429 during preparation; exact current creation/use-case labels could not be verified.'
    say 'If no suitable app exists, use the official app guide; do not guess a use case or broaden permissions.'
    open_url 'https://developers.facebook.com/docs/apps/'
    if confirm 'Do you approve selecting or creating an isolated Meta app through the current official guide?'; then
      if capture O01_META_APP_ID 'App ID (digits; blank leaves pending):' '^[0-9]+$'; then
        checkpoint O01_META_APP_SELECTION 'Confirm this is the intended isolated app and its required setup is complete?'
      else
        write_env O01_META_APP_SELECTION 'pending'
        SKIPPED+=('Meta app selection')
      fi
    else
      write_env O01_META_APP_SELECTION 'pending'
      SKIPPED+=('Meta app selection')
    fi
  else
    say 'Skipped: TikTok-only run.'
  fi

  stage 'Meta: account and reporting-access approval'
  if [[ "$provider_scope" != tiktok ]]; then
    open_url 'https://adsmanager.facebook.com/'
    step 'Select the authorized isolated ad account in the account selector.'
    step 'Copy its numeric ID from the selected account or act= in the address; paste only the ID.'
    capture O01_META_ACCOUNT_ID 'Ad account ID (digits; blank leaves pending):' '^[0-9]+$' || SKIPPED+=('Meta account ID')
    say 'Read the account timezone from its settings without changing it. Unknown can remain pending.'
    capture O01_META_ACCOUNT_ZONE 'Displayed timezone (blank leaves pending):' "$text_pattern" || SKIPPED+=('Meta account zone')
    open_url 'https://business.facebook.com/settings/'
    say 'The principal needs access to the selected asset as well as a suitable app/token grant.'
    say 'Reporting candidate: ads_read. Reporting, inventory and account metadata still need endpoint-specific validation.'
    say 'The current minimum scope/role and review requirements are unresolved; this wizard does not prescribe an unverified grant path.'
    say 'If the dashboard lacks a documented reporting-only path, leave pending. Do not add management scopes as a workaround.'
    if confirm 'Approve only the documented reporting-access assignment for this app/account, if available?'; then
      step 'Complete the documented assignment yourself; review the selected assets and every permission before saving.'
      capture O01_META_ROLE_LABEL 'Exact reporting role label you assigned (blank leaves pending):' "$text_pattern" || SKIPPED+=('Meta role')
      capture O01_META_PERMISSION_LABELS 'Exact reporting permission labels (blank leaves pending):' "$text_pattern" || SKIPPED+=('Meta permissions')
      checkpoint O01_META_ACCESS_REVIEW 'Have you completed and reviewed that assignment for only the selected isolated account?'
    else
      write_env O01_META_ACCESS_REVIEW 'pending'
      SKIPPED+=('Meta reporting access')
    fi
  else
    say 'Skipped: TikTok-only run.'
  fi

  stage 'TikTok: API for Business login and app selection'
  if [[ "$provider_scope" != meta ]]; then
    open_url 'https://business-api.tiktok.com/portal/'
    step 'Sign in yourself. Use API for Business > My Apps and select the isolated developer app.'
    say 'Use the developer app, not an Events Manager App ID or a consumer Login Kit app.'
    say 'If developer registration or app creation is needed, follow Get Started > Register as developer / Create a developer app.'
    say 'Those creation forms are account-dependent; if the documented path differs or is unavailable, leave pending.'
    if confirm 'Approve selecting or creating this isolated TikTok developer app through its official setup flow?'; then
      step 'Open the selected app > Basic Information and locate its developer App ID.'
      if capture O01_TIKTOK_APP_ID 'Developer App ID (letters/digits/_/-; blank leaves pending):' '^[a-zA-Z0-9_-]+$'; then
        checkpoint O01_TIKTOK_APP_SELECTION 'Confirm the selected app and its developer registration are ready?'
      else
        write_env O01_TIKTOK_APP_SELECTION 'pending'
        SKIPPED+=('TikTok app selection')
      fi
    else
      write_env O01_TIKTOK_APP_SELECTION 'pending'
      SKIPPED+=('TikTok app selection')
    fi
  else
    say 'Skipped: Meta-only run.'
  fi

  stage 'TikTok: advertiser account and reporting-role approval'
  if [[ "$provider_scope" != meta ]]; then
    open_url 'https://ads.tiktok.com/i18n/'
    step 'In Ads Manager, use the account-name dropdown at the top right to find the advertiser ID.'
    capture O01_TIKTOK_ADVERTISER_ID 'Advertiser ID (digits; blank leaves pending):' '^[0-9]+$' || SKIPPED+=('TikTok advertiser ID')
    step 'Use Tools > Settings > Account setup > My account > Basic information, where available, to inspect account details.'
    capture O01_TIKTOK_ACCOUNT_ZONE 'Displayed timezone (blank leaves pending):' "$text_pattern" || SKIPPED+=('TikTok account zone')
    open_url 'https://business.tiktok.com/'
    say 'If access already exists, inspect it rather than requesting another grant.'
    say 'If a Business Center request is necessary, only its admin can request it; the owner must approve it.'
    if confirm 'Approve reviewing existing Analyst access or requesting it for only this isolated advertiser if absent?'; then
      step 'If access exists, inspect its role and account; skip the request steps below.'
      step 'If absent: Business Center > Accounts > Advertiser accounts > Add advertiser account > Request Access.'
      step 'For a new request, enter this advertiser ID, select Analyst, review the account, then submit.'
      step 'For a new request, the owner reviews Ads Manager notifications > Business Center before accepting.'
      say 'Analyst is a reporting-role candidate; API endpoint authorization still needs validation.'
      checkpoint O01_TIKTOK_ROLE_REVIEW 'Is Analyst access now assigned and approved for the selected advertiser?'
    else
      write_env O01_TIKTOK_ROLE_REVIEW 'pending'
      SKIPPED+=('TikTok advertiser role approval')
    fi
    open_url 'https://business-api.tiktok.com/portal/'
    step 'My Apps > selected app: review the requested reporting permissions.'
    say 'Reporting > Consolidated Report is the v2 reporting candidate; inventory/metadata read access must be checked separately.'
    say 'Leave pending if review is required or the required read-only permission set is unclear.'
    capture O01_TIKTOK_PERMISSION_LABELS 'Exact reporting permission labels shown (blank leaves pending):' "$text_pattern" || SKIPPED+=('TikTok reporting permissions')
  else
    say 'Skipped: Meta-only run.'
  fi

  stage 'TikTok: explicit advertiser consent checkpoint'
  if [[ "$provider_scope" != meta ]]; then
    open_url 'https://business-api.tiktok.com/portal/'
    say 'This repository has no reporting OAuth callback or token-exchange implementation.'
    say 'Default: leave authorization pending until a working, controlled callback and secure server-side exchange exist.'
    say 'Do not use a public demo URL or an arbitrary third-party callback. Keep codes and tokens out of chat and this file.'
    if confirm 'Is a separate working callback and secure exchange already ready for this isolated app?'; then
      if confirm 'Approve advertiser authorization for the selected app, permissions and isolated advertiser only?'; then
        step 'My Apps > selected app > Basic Information > Advertiser authorization URL.'
        step 'Open that URL yourself. Review permissions and account, then consent and complete provider identity verification.'
        step 'Let the controlled callback receive the code and its secure exchange obtain/store the token.'
        checkpoint O01_TIKTOK_AUTHORIZATION 'Did that flow finish successfully for the selected app/account?'
      else
        write_env O01_TIKTOK_AUTHORIZATION 'pending'
        SKIPPED+=('TikTok advertiser authorization')
      fi
    else
      write_env O01_TIKTOK_AUTHORIZATION 'pending'
      SKIPPED+=('TikTok callback, token exchange and advertiser authorization')
    fi
  else
    say 'Skipped: Meta-only run.'
  fi

  stage 'Historical evidence and handoff'
  if [[ "$provider_scope" != tiktok ]]; then
    open_url 'https://adsmanager.facebook.com/'
    checkpoint O01_META_HISTORY_AVAILABLE 'Does the selected account have approved reference delivery, zero controls and relevant boundary history?'
  fi
  if [[ "$provider_scope" != meta ]]; then
    open_url 'https://ads.tiktok.com/i18n/'
    checkpoint O01_TIKTOK_HISTORY_AVAILABLE 'Does the selected advertiser have approved reference delivery, zero controls and relevant boundary history?'
  fi
  say 'Missing history remains a validation prerequisite; no ads or spend are requested by this wizard.'
  write_env O01_SETUP_STATUS 'metadata_recorded_validation_pending'
  write_env O01_SETUP_RECORDED_AT "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  finish
  say 'Only the guided setup record is complete. O-01 remains OPEN; all reporting tests are NOT RUN.'
  say "Local record: $ENV_FILE"
  say 'Next: inspect pending fields, resolve the callback/access prerequisites, then run the authorized read-only validation matrix.'
  say 'Do not source or publish the setup file. No credentials were collected.'
}

run_wizard "$@"; exit
